Test("service_fixed_profiles_and_empty_controls",[]{auto q=ReconstructionQueue::Create(root/"empty-service","fixture");ProjectReconstruction s(*q,fs::path{});Need(s.ListExecutions().empty(),"Empty history");Need(!s.Snapshot().progress.completedIterations&&!s.Snapshot().timing.activeMilliseconds,"Fabricated initial counts/time");Need(!s.RequestPause()&&!s.RequestForceStop(),"Idle controls accepted");s.SetPreparationActiveMilliseconds(321);Need(Throws([&]{s.SetPreparationActiveMilliseconds(std::numeric_limits<uint64_t>::max());}),"Prefix overflow accepted");auto low=GetReconstructionProfileSettings(ReconstructionProfile::Low),med=GetReconstructionProfileSettings(ReconstructionProfile::Medium),high=GetReconstructionProfileSettings(ReconstructionProfile::High);Need(low.brushSteps==300&&low.maxResolution==512&&low.maxSplats==25000,"Low settings");Need(med.brushSteps==600&&med.maxResolution==640&&med.maxSplats==50000,"Medium settings");Need(high.brushSteps==1200&&high.maxResolution==960&&high.maxSplats==100000,"High settings");Need(Throws([]{GetReconstructionProfileSettings(ReconstructionProfile::Advanced);}),"Advanced silently fixed");});
Test("service_metadata_only_history_no_usable_output_no_latest_mutation",[]{auto q=ReconstructionQueue::Create(root/"history","fixture");auto id=std::string("11111111-1111-4111-8111-111111111111");auto path=q->Directory()/"executions"/id/"native-state-1.json";auto o=Metadata(id,q->Snapshot().projectId,"Completed");Json(path,o);auto before=Read(q->Directory()/"project.mstudio");ProjectReconstruction s(*q,fs::path{});auto rows=s.ListExecutions();Need(rows.size()==1&&rows[0].state==ExecutionState::Completed,"Metadata not listed");Need(rows[0].output.empty()&&!rows[0].initialView&&rows[0].outputSha256.empty()&&!rows[0].resultGeneration,"Metadata claimed verified output");Need(!rows[0].timing.activeMilliseconds&&!rows[0].timing.completedUtc,"Legacy time inferred");Need(Throws([&]{s.InspectExecution(id);}),"Unsealed history accepted");Need(Throws([&]{s.InspectExecution("../escape");}),"Traversal id accepted");Need(!fs::exists(q->Directory()/"executions/latest.json")&&Read(q->Directory()/"project.mstudio")==before,"History inspection changed latest/plan");});
Test("service_progress_timing_schema_and_publication_bounds",[]{int i=0;for(const auto&kind:{"legacy","prezero","pre599","target_unpublished","unknown_timing","completion_unpublished","interrupted"}){auto q=ReconstructionQueue::Create(root/(std::string("metadata-")+kind),"fixture");auto id=std::string("22222222-2222-4222-8222-222222222222");auto o=Metadata(id,q->Snapshot().projectId,strcmp(kind,"interrupted")==0?"Training":"Failed");if(strcmp(kind,"legacy")!=0){int n=strcmp(kind,"prezero")==0?0:strcmp(kind,"target_unpublished")==0?600:599;o["progress"]=QJsonObject{{"schemaVersion",1},{"observedIteration",std::min(n,599)},{"completedIterations",n},{"totalIterations",600},{"sampleSequence",std::min(n,599)}};o["timing"]=QJsonObject{{"schemaVersion",strcmp(kind,"unknown_timing")==0?999:1},{"activeMilliseconds",1234},{"startedUtc","2026-10-24T01:00:00.000Z"},{"completedUtc",strcmp(kind,"completion_unpublished")==0?QJsonValue("2026-10-24T02:00:00.000Z"):QJsonValue(QJsonValue::Null)},{"activeTimeComplete",true}};}auto path=q->Directory()/"executions"/id/"native-state-1.json";Json(path,o);auto bytes=Read(path);ProjectReconstruction s(*q,fs::path{});bool reject=strcmp(kind,"target_unpublished")==0||strcmp(kind,"unknown_timing")==0||strcmp(kind,"completion_unpublished")==0;if(reject)Need(Throws([&]{s.ListExecutions();}),"Invalid metadata accepted");else{auto row=s.ListExecutions().at(0);if(strcmp(kind,"legacy")==0)Need(!row.timing.activeMilliseconds,"Legacy guessed");else{Need(row.progress.completedIterations==(strcmp(kind,"prezero")==0?0:599),"Pre-step off by one");Need(row.timing.activeMilliseconds==1234,"Known interval changed");if(strcmp(kind,"interrupted")==0)Need(row.state==ExecutionState::Interrupted&&!row.timing.activeTimeComplete,"Crash time complete");}}Need(Read(path)==bytes,"Schema inspection mutated bytes");++i;}});
Test("service_timing_boundary_strict_optional_legacy_and_readonly",[]{int n=0;for(auto boundary:QList<QJsonValue>{QJsonValue(QJsonValue::Undefined),QJsonValue("preparation_start_v1"),QJsonValue("execution_start_v1"),QJsonValue("future_boundary_v9"),QJsonValue(7),QJsonValue(QJsonValue::Null)}){auto q=ReconstructionQueue::Create(root/("boundary-"+std::to_string(n++)),"fixture");auto id=std::string("44444444-4444-4444-8444-444444444444");auto o=Metadata(id,q->Snapshot().projectId);QJsonObject timing{{"schemaVersion",1},{"activeMilliseconds",1234},{"startedUtc","2026-10-24T01:00:00.000Z"},{"completedUtc",QJsonValue(QJsonValue::Null)},{"activeTimeComplete",true}};if(!boundary.isUndefined())timing["startedBoundary"]=boundary;o["timing"]=timing;auto path=q->Directory()/"executions"/id/"native-state-1.json";Json(path,o);auto bytes=Read(path);ProjectReconstruction service(*q,{});if(boundary.isUndefined()||boundary==QJsonValue("preparation_start_v1")||boundary==QJsonValue("execution_start_v1")){auto rows=service.ListExecutions();Need(rows.size()==1,"Valid timing metadata rejected");Need(rows[0].timing.startedBoundary.has_value()==!boundary.isUndefined(),"Legacy timing provenance invented");if(!boundary.isUndefined())Need(*rows[0].timing.startedBoundary==boundary.toString().toStdString(),"Provenance changed");}else Need(Throws([&]{service.ListExecutions();}),"Unknown/nonstring timing provenance accepted");Need(Read(path)==bytes,"Inspection rewrote timing metadata");}});
